import SwiftUI

/// Recurring service agreements — maintenance contracts, annual services and
/// anything else that repeats.
///
/// The jobs themselves are generated by a scheduled server task, not by this
/// screen and not by the app being open. That matters: a contract that only
/// produces its next visit when somebody happens to launch an iPhone is not a
/// contract. This screen sets the arrangement up and reports what the server
/// has produced from it.
struct RecurringServiceView: View {
    @Environment(AppEnvironment.self) private var env
    @State private var viewModel = RecurringServiceViewModel()
    @State private var editing: RecurringDraftBox?
    @State private var pendingDelete: RecurringServiceRow?

    private var session: TenantSession? { env.activeSession }
    private var terms: Terminology { env.terms }

    var body: some View {
        ScrollView {
            content
                .padding(.horizontal, Theme.margin)
                .padding(.bottom, 28)
        }
        .background(Theme.canvas)
        .navigationTitle("Recurring service")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar(.hidden, for: .tabBar)
        .toolbar {
            if viewModel.state.value?.canManage == true {
                ToolbarItem(placement: .primaryAction) {
                    Button {
                        editing = RecurringDraftBox(RecurringServiceDraft())
                    } label: {
                        Image(systemName: "plus")
                    }
                    .accessibilityLabel("New recurring visit")
                }
            }
        }
        .task(id: session?.userID) { await reload() }
        .refreshable { await reload(showLoading: false) }
        .sheet(item: $editing) { box in
            RecurringServiceEditorView(
                draft: box.draft,
                options: viewModel.options ?? .empty
            ) { updated in
                guard let session else { return false }
                return await viewModel.save(gateway: env.gateway, session: session, draft: updated)
            }
        }
        .alert(
            "Remove this recurring visit?",
            isPresented: Binding(
                get: { pendingDelete != nil },
                set: { if !$0 { pendingDelete = nil } }
            )
        ) {
            Button("Remove", role: .destructive) {
                if let row = pendingDelete, let session {
                    Task { await viewModel.delete(gateway: env.gateway, session: session, id: row.id) }
                }
                pendingDelete = nil
            }
            Button("Keep", role: .cancel) { pendingDelete = nil }
        } message: {
            Text("No more visits will be booked from it. Jobs already created stay exactly as they are.")
        }
        .alert(
            "Something went wrong",
            isPresented: Binding(
                get: { viewModel.actionError != nil },
                set: { if !$0 { viewModel.actionError = nil } }
            )
        ) {
            Button("OK", role: .cancel) { viewModel.actionError = nil }
        } message: {
            Text(viewModel.actionError ?? "")
        }
    }

    @ViewBuilder
    private var content: some View {
        switch viewModel.state {
        case .idle, .loading:
            LoadingStateView(message: "Loading recurring service")
        case .failed(let error):
            ErrorStateView(error: error) { Task { await reload() } }
        case .loaded(let board):
            loaded(board)
        }
    }

    @ViewBuilder
    private func loaded(_ board: RecurringServiceBoard) -> some View {
        if board.agreements.isEmpty {
            EmptyStateView(
                symbolName: "arrow.triangle.2.circlepath",
                title: "No recurring visits",
                message: board.canManage
                    ? "Set up a maintenance contract and the visits book themselves."
                    : "Nothing recurring is set up for this company."
            )
            .padding(.top, 40)
        } else {
            VStack(alignment: .leading, spacing: 20) {
                if let confirmation = viewModel.confirmation {
                    confirmationBanner(confirmation)
                }

                summaryCard(board)

                VStack(alignment: .leading, spacing: 8) {
                    Text("Agreements")
                        .sectionLabelStyle()

                    VStack(spacing: 10) {
                        ForEach(board.agreements) { row in
                            agreementCard(row, canManage: board.canManage)
                        }
                    }
                }

                Text("Visits are booked automatically by the scheduler, whether or not anyone has the app open.")
                    .font(.caption)
                    .foregroundStyle(Theme.meta)
                    .fixedSize(horizontal: false, vertical: true)
            }
            .padding(.top, 4)
        }
    }

    private func confirmationBanner(_ message: String) -> some View {
        HStack(alignment: .top, spacing: 10) {
            Image(systemName: "checkmark.circle.fill")
                .font(.footnote)
                .foregroundStyle(Theme.green)
            Text(message)
                .font(.footnote)
                .foregroundStyle(Theme.ink)
                .fixedSize(horizontal: false, vertical: true)
            Spacer(minLength: 4)
            Button {
                withAnimation(.snappy) { viewModel.confirmation = nil }
            } label: {
                Image(systemName: "xmark")
                    .font(.caption)
                    .foregroundStyle(Theme.meta)
            }
            .buttonStyle(.plain)
        }
        .padding(14)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Theme.green.opacity(0.10))
        .clipShape(.rect(cornerRadius: Theme.cardRadius))
    }

    private func summaryCard(_ board: RecurringServiceBoard) -> some View {
        HStack(spacing: 0) {
            summaryTile("Active", value: "\(board.activeCount)", tone: Theme.ink)
            Divider().frame(height: 34)
            summaryTile(
                "Due now",
                value: "\(board.dueCount)",
                tone: board.dueCount > 0 ? Theme.amber : Theme.ink
            )
        }
        .padding(.vertical, 14)
        .frame(maxWidth: .infinity)
        .cardSurface()
    }

    private func summaryTile(_ title: String, value: String, tone: Color) -> some View {
        VStack(spacing: 3) {
            Text(value)
                .font(.title2.weight(.bold))
                .monospacedDigit()
                .foregroundStyle(tone)
            Text(title)
                .font(.caption)
                .foregroundStyle(Theme.meta)
        }
        .frame(maxWidth: .infinity)
    }

    private func agreementCard(_ row: RecurringServiceRow, canManage: Bool) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Text(row.title)
                    .font(.subheadline.weight(.semibold))
                    .foregroundStyle(Theme.ink)
                Spacer(minLength: 4)
                if !row.isActive {
                    StatusPill(badge: StatusBadge(text: "Paused", tone: .neutral))
                } else if row.isDue {
                    StatusPill(badge: StatusBadge(text: "Due", tone: .warning))
                }
            }

            Text(row.customerName)
                .font(.footnote.weight(.medium))
                .foregroundStyle(Theme.secondary)

            Text(row.siteLine)
                .font(.caption)
                .foregroundStyle(Theme.meta)
                .fixedSize(horizontal: false, vertical: true)

            Divider()

            HStack(spacing: 10) {
                Label(row.frequencyLabel, systemImage: "repeat")
                    .font(.caption)
                    .foregroundStyle(Theme.secondary)
                Spacer(minLength: 4)
                Label(
                    "Next \(Formatters.shortDate(row.nextDueDate))",
                    systemImage: "calendar"
                )
                .font(.caption)
                .monospacedDigit()
                .foregroundStyle(row.isDue && row.isActive ? Theme.amber : Theme.secondary)
            }

            if let last = row.lastGeneratedOn {
                Text("Last booked \(Formatters.shortDate(last))")
                    .font(.caption2)
                    .foregroundStyle(Theme.meta)
            }

            if canManage {
                HStack(spacing: 14) {
                    Button("Edit") {
                        editing = RecurringDraftBox(RecurringServiceDraft(
                            id: row.id,
                            customerID: row.customerID,
                            addressID: "",
                            title: row.title,
                            frequency: row.frequency,
                            intervalDays: row.intervalDays ?? 90,
                            nextDueDate: row.nextDueDate,
                            isActive: row.isActive
                        ))
                    }
                    .font(.footnote.weight(.semibold))
                    .foregroundStyle(Theme.primary)

                    Button("Remove") { pendingDelete = row }
                        .font(.footnote.weight(.semibold))
                        .foregroundStyle(Theme.red)

                    Spacer()
                }
                .padding(.top, 2)
            }
        }
        .padding(14)
        .frame(maxWidth: .infinity, alignment: .leading)
        .cardSurface()
    }

    private func reload(showLoading: Bool = true) async {
        guard let session else { return }
        await viewModel.load(gateway: env.gateway, session: session, showLoading: showLoading)
    }
}

/// `sheet(item:)` needs an `Identifiable`, and `RecurringServiceDraft` already
/// owns an optional `id` meaning "the record being edited". Conforming the
/// draft itself would collide with that field, so presentation identity gets
/// its own wrapper instead of overloading a domain property.
struct RecurringDraftBox: Identifiable {
    let id: String
    let draft: RecurringServiceDraft

    init(_ draft: RecurringServiceDraft) {
        self.id = draft.id ?? "new"
        self.draft = draft
    }
}
